import React from "react";
import { motion } from "framer-motion";

function Hero() {
  return (
  <section className="hero">
  <div className="hero-left">
    <h1>
      Building <br />
      Modern Web <br />
      Experiences
    </h1>

    <p>
      Frontend developer focused on clean UI & smooth UX
    </p>

    <button>View Projects</button>
  </div>
</section>
  );
}

export default Hero;
